346				HttpServletRequest req) throws Exception {
347			
348			logger.info("[STEP 1] - Vaildation Check");
349			int maxSize5MB = 1024 * 1024 * 5;
350			int maxSize1MB = 1024 * 1024 * 1;
351			param.put("managerNames", managerNames);
352			param.put("managerPhones", managerPhones);
353			param.put("managerConsentFormExceptions", managerConsentFormExceptions);
354			
355			//고객사 로고 (Web)
356			if (clientLogo != null) {
357				if (!CommonUtil.imgFileExtCheck(CommonUtil.getFileExt(clientLogo.getOriginalFilename()))) {
358					throw new LogicException("VALIDATION_FAIL","003");
359				}
360				if (maxSize5MB < clientLogo.getSize()) {
361					throw new LogicException("VALIDATION_FAIL","004");
362				}
363			}
364			//고객사 로고 (APP)
365			if (clientNameImg != null) {
366				if (!CommonUtil.imgFileExtCheck(CommonUtil.getFileExt(clientNameImg.getOriginalFilename()))) {
367					throw new LogicException("VALIDATION_FAIL","003");
368				}
369				if (maxSize1MB < clientNameImg.getSize()) {
370					throw new LogicException("VALIDATION_FAIL","004");
371				}
372			}
373			
374			//고객사 APP 배경
375			if (clientAppBkgdImg != null) {
376				if (!CommonUtil.imgFileExtCheck(CommonUtil.getFileExt(clientAppBkgdImg.getOriginalFilename()))) {
377					throw new LogicException("VALIDATION_FAIL","003");
378				}
379				if (maxSize1MB < clientAppBkgdImg.getSize()) {
380					throw new LogicException("VALIDATION_FAIL","004");
381				}
382			}
383			
384			//장애대응담당자 개인정보활용동의서
385			if (incidentConsentFormImg != null) {
386				if (!CommonUtil.imgFileExtCheck(CommonUtil.getFileExt(incidentConsentFormImg.getOriginalFilename()))) {
387					throw new LogicException("VALIDATION_FAIL","003");
388				}
389				if (maxSize5MB < incidentConsentFormImg.getSize()) {
390					throw new LogicException("VALIDATION_FAIL","004");
391				}
392			} else {
393				String incidentManagerName = param.getString("incidentManagerName");
394				if (incidentConsentFormExceptionYn == null || "n".equals(incidentConsentFormExceptionYn)) {
395					if (incidentManagerName != null && !"".equals(incidentManagerName)) {
396						if (beforeIncidentConsentFormUrl == null || beforeIncidentConsentFormUrl.isEmpty()) {
397							throw new LogicException("VALIDATION_FAIL", "250");
398						}
399					}
400				}
401			}
402			
403			//담당자 개인정보활용동의서
404			if (managerConsentFormImg != null) {
405				int index = 0;
406				for (MultipartFile managerConsentFormImgInfo : managerConsentFormImg) {
407					if (managerConsentFormImgInfo.isEmpty()) {
408						if (managerConsentFormExceptions[index].isEmpty() || "n".equals(managerConsentFormExceptions[index])) {
409							if (beforeManagerConsentFormUrl[index].isEmpty() || "".equals(beforeManagerConsentFormUrl[index])) {
410								throw new LogicException("VALIDATION_FAIL", "250");
411							}
412						}
413						index++;
414						continue;
415					}
416					
417					//장애대응담당자 개인정보활용동의서
418					if (managerConsentFormImgInfo != null) {
419						if (!CommonUtil.imgFileExtCheck(CommonUtil.getFileExt(managerConsentFormImgInfo.getOriginalFilename()))) {
420							throw new LogicException("VALIDATION_FAIL","003");
421						}
422						if (maxSize5MB < managerConsentFormImgInfo.getSize()) {
423							throw new LogicException("VALIDATION_FAIL","004");
424						}
425					}
426					index++;
427				}
428			}
429			
430			if (CommonUtil.isVulnerability(new String[] {"clientName", "sqlSessionTemplate", "managerName", "smartphoneApn", "iotApn", "subTitles"
431					, "knoxEnterpriseLisenceKey", "knoxLisenceKey", "joinSoc", "serviceId1", "serviceId2", "serviceId3", "qosControlId"
432					, "beforeIncidentConsentFormUrl", "beforeManagerConsentFormUrl"}, param)) {
433				throw new LogicException("VULNERABLE_VALUE", "002");
434			}
435			param.put("clientSeq", clientSeq);
436			param.put("policySeq", param.getLong("policySeq"));
437			param.put("beforeIncidentConsentFormUrl", beforeIncidentConsentFormUrl);
438			param.put("beforeManagerConsentFormUrl", beforeManagerConsentFormUrl);
439			param.put("clientUptAccountSeq", param.getSessionAttribute("loginAccountSeq"));
440			model.addAllAttributes(service.modifyClient(param, clientLogo, clientAppBkgdImg, clientNameImg, incidentConsentFormImg, managerConsentFormImg, req)); 
441			return JSON_VIEW;
442		}
