248			String existingTestUserYn = param.getString("existingTestUserYn");
249			if (consentFormImg != null && (!CommonUtil.isNull(existingTestUserYn) && "N".equals(existingTestUserYn))) {
250				if (!CommonUtil.imgFileExtCheck(CommonUtil.getFileExt(consentFormImg.getOriginalFilename()))) {
251					throw new LogicException("VALIDATION_FAIL","003");
252				}
253				if (maxSize5MB < consentFormImg.getSize()) {
254					throw new LogicException("VALIDATION_FAIL","004");
255				}
256			}
257			
258			param.put("clientSeq", param.getSessionAttribute("loginClientSeq"));
259			param.put("accountSeq", param.getSessionAttribute("loginAccountSeq"));
260			param.put("memberSeq", memberSeq);
261			model.addAllAttributes(service.modifyMember(param, consentFormImg));
262			return JSON_VIEW;
263		}
