package com.ahope.ds.web.admin.member.controller;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.MediaType;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestMethod;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RequestPart;
import org.springframework.web.multipart.MultipartFile;

import com.ahope.ds.common.bean.ParamMap;
import com.ahope.ds.common.exception.LogicException;
import com.ahope.ds.common.extension.annotation.History;
import com.ahope.ds.common.extension.annotation.History.HistoryType;
import com.ahope.ds.common.extension.annotation.RequestJson;
import com.ahope.ds.common.extension.annotation.RequestParamMap;
import com.ahope.ds.common.util.CommonUtil;
import com.ahope.ds.common.web.controller.CommonController;
import com.ahope.ds.web.admin.member.service.MemberService;

import io.swagger.v3.oas.annotations.Operation;
import io.swagger.v3.oas.annotations.Parameter;
import io.swagger.v3.oas.annotations.Parameters;
import io.swagger.v3.oas.annotations.enums.ParameterIn;
import io.swagger.v3.oas.annotations.media.Content;
import io.swagger.v3.oas.annotations.media.ExampleObject;
import io.swagger.v3.oas.annotations.media.Schema;
import io.swagger.v3.oas.annotations.parameters.RequestBody;
import io.swagger.v3.oas.annotations.tags.Tag;

@Tag(name = "Member", description = "가입자 관리 API")
@Controller
@RequestMapping("/web/admin/members")
public class MemberController extends CommonController {

	@Autowired
	private MemberService service;

	/**
	 * 가입현황 화면 조회
	 */
	@Operation(summary = "가입현황 화면", description = "가입현황 관리 화면을 조회합니다.")
	@RequestMapping(value = "", method = RequestMethod.GET)
	public String memberTotalView(@RequestParamMap ParamMap param, Model model) throws Exception {
		param.put("clientSeq", param.getSessionAttribute("loginClientSeq"));
		model.addAllAttributes(service.getClientUsimMovementAllowed(param));
		return "admin/member/memberManagement";
	}

	/**
	 * 목록 데이터 조회 (datatable)
	 */
	@Operation(summary = "가입자 목록 조회", description = "가입자 목록을 DataTable 형식으로 조회합니다.")
	@Parameters({
		@Parameter(name = "start", description = "페이지 시작 위치", example = "0", schema = @Schema(type = "integer", format = "int32")),
		@Parameter(name = "length", description = "페이지 크기", example = "10", schema = @Schema(type = "integer", format = "int32")),
		@Parameter(name = "searchCorporation", description = "법인여부 검색 (1:법인, 0:개인)", example = "1", schema = @Schema(type = "string")),
		@Parameter(name = "searchTestUserYn", description = "테스트 유저여부 (Y: 테스트, N: 일반)색", example = "N", schema = @Schema(type = "string")),
		@Parameter(name = "searchOs", description = "OS (0: Android, 9: 기타)", example = "0", schema = @Schema(type = "string")),
		@Parameter(name = "searchConnectionStatus", description = "접속현황 (01: 접속중, 02: 미접속)", example = "01", schema = @Schema(type = "string")),
		@Parameter(name = "searchJoinStatus", description = "가입 현황 (01: 완료, 02: 가입요청, 03: 해지요청, 06: 해지, 07: 가입실패, 08: 해지실패)", example = "01", schema = @Schema(type = "string")),
		@Parameter(name = "searchExceptionPolicy", description = "예외 정책 (0: 없음, 1: VIP, 2: 예외1, 3: 예외2, 4: 예외3)", example = "1", schema = @Schema(type = "string")),
		@Parameter(name = "searchType", description = "검색 타입 (CTN: 전화번호, MANAGER_NAME: 사용자, NOTE: 비고)", example = "CTN", schema = @Schema(type = "string")),
		@Parameter(name = "searchValue", description = "검색어", example = "01022224444", schema = @Schema(type = "string")),
		@Parameter(name = "searchInternetBlock", description = "인터넷 차단 (01: 등록, 02: 해지, 03: 등록 실패, 04: 해지 실패)", example = "01", schema = @Schema(type = "string")),
		@Parameter(name = "unmaskingYn", description = "마스킹해제 (true: 마스킹 해제, false: 마스킹)", example = "true", schema = @Schema(type = "boolean")),
		@Parameter(name = "reason", description = "마스킹 해제 사유", example = "마스킹 해제 사유입니다.", schema = @Schema(type = "string"))
	})
	@History(historyType = {HistoryType.PERSONAL_INFO_ACCESS, HistoryType.UNMASK}, reqType = "join_status")
	@RequestMapping(value = "/ajax", method = RequestMethod.GET)
	public String memberList(@RequestParamMap ParamMap param, Model model) throws Exception{
		param.put("clientSeq", param.getSessionAttribute("loginClientSeq"));
		model.addAllAttributes(service.getMemberList(param));
		return JSON_VIEW;
	}

	/**
	 * 가입현황(LGC) 조회
	 */
	@Operation(summary = "가입현황 통계", description = "가입현황 통계 정보를 조회합니다.")
	@RequestMapping(value = "/total", method = RequestMethod.GET)
	public String getMemberTotalCount(@RequestParamMap ParamMap param, Model model) {
		param.put("clientSeq", param.getSessionAttribute("loginClientSeq"));
		model.addAllAttributes(service.getMemberTotalInfo(param));
		return JSON_VIEW;
	}

	/**
	 * 가입자 등록
	 */
	@Operation(summary = "가입자 등록", description = "새 가입자를 등록합니다.")
	@Parameters({
		@Parameter(name = "ctn", description = "전화번호", example = "01012345678", required = true, schema = @Schema(type = "string")),
		@Parameter(name = "os", description = "OS (0: Android)", example = "0", schema = @Schema(type = "string")),
		@Parameter(name = "exceptionPolicy", description = "예외정책 (0: 일반, 1: VIP, 2: 예외1, 3: 예외2, 4: 예외3)", example = "0", required = true, schema = @Schema(type = "string")),
		@Parameter(name = "managerName", description = "담당자명", example = "홍길동", required = true, schema = @Schema(type = "string")),
		@Parameter(name = "corporationYn", description = "법인여부 (1: 법인, 0: 개인)", example = "1", required = true, schema = @Schema(type = "string")),
		@Parameter(name = "immediately", description = "즉시 가입 여부", example = "true", required = true, schema = @Schema(type = "boolean")),
		@Parameter(name = "testUserYn", description = "테스트 사용자 여부 (Y/N)", example = "N", schema = @Schema(type = "string")),
		@Parameter(name = "banSolns", description = "차단 솔루션 목록 (콤마 구분)", example = "1,2,3", schema = @Schema(type = "string")),
		@Parameter(name = "noteLen", description = "메모 개수", example = "2", schema = @Schema(type = "integer", format = "int32")),
		@Parameter(name = "notes[0]", description = "메모1", example = "첫번째 메모입니다", schema = @Schema(type = "string")),
		@Parameter(name = "notes[1]", description = "메모2", example = "두번째 메모입니다", schema = @Schema(type = "string"))
	})
	@RequestMapping(value = "", method = RequestMethod.POST, consumes = MediaType.MULTIPART_FORM_DATA_VALUE)
	public String createMember(@RequestParamMap(requiredValues= {"ctn", "exceptionPolicy","managerName","corporationYn","immediately"}) ParamMap param, 
			@Parameter(description = "개인정보 활용동의서 이미지 파일") @RequestParam (value="consentFormImg", required=false) MultipartFile consentFormImg, Model model) throws Exception{
		int maxSize5MB = 1024 * 1024 * 5;

		if (CommonUtil.isVulnerability(new String[] {"managerName"}, param)) {
			throw new LogicException("VULNERABLE_VALUE", "002");
		}

		if (!CommonUtil.isNum(param.getString("noteLen"))) {
			throw new LogicException("VULNERABLE_VALUE", "002");
		}
		for (int i = 0; i < param.getInt("noteLen"); i++) {
			if (CommonUtil.isVulnerability(new String[] {"notes["+i+"]"}, param)) {
				throw new LogicException("VULNERABLE_VALUE", "002");
			}
		}

		//개인정보활용동의서
		if (consentFormImg != null) {
			if (!CommonUtil.imgFileExtCheck(CommonUtil.getFileExt(consentFormImg.getOriginalFilename()))) {
				throw new LogicException("VALIDATION_FAIL","003");
			}
			if (maxSize5MB < consentFormImg.getSize()) {
				throw new LogicException("VALIDATION_FAIL","004");
			}
		}

		param.put("accountSeq", param.getSessionAttribute("loginAccountSeq"));
		param.put("clientSeq", param.getSessionAttribute("loginClientSeq"));
		model.addAllAttributes(service.createMember(param, consentFormImg));
		return JSON_VIEW;
	}

	/**
	 * 엑셀 등록
	 */
	@Operation(summary = "가입자 엑셀 업로드", description = "엑셀 파일로 가입자를 일괄 등록합니다.")
	@RequestMapping(value = "/excel", method = RequestMethod.POST, consumes = MediaType.MULTIPART_FORM_DATA_VALUE)
	public String createMemberExcelUpload(@RequestParamMap ParamMap param, Model model
			, @Parameter(name = "memberExcelFile", description = "가입자 등록 엑셀파일")@RequestPart("memberExcelFile") MultipartFile memberExcelFile) throws LogicException {
		param.put("accountSeq", param.getSessionAttribute("loginAccountSeq"));
		param.put("clientSeq", param.getSessionAttribute("loginClientSeq"));
		if (!CommonUtil.excelFileExtCheck(CommonUtil.getFileExt(memberExcelFile.getOriginalFilename()))){
			throw new LogicException("VALIDATION_FAIL","003");
		}
		model.addAllAttributes(service.createMemberExcelUpload(param, memberExcelFile));
		return JSON_VIEW;
	}

	/**
	 * 엑셀 업로드 완료 여부 체크
	 */
	@Operation(summary = "엑셀 업로드 상태 확인", description = "엑셀 업로드 완료 여부를 확인합니다.")
	@RequestMapping(value = "/excel/upload/check", method = RequestMethod.GET)
	public String checkExcelUpload(@RequestParamMap ParamMap param, Model model) {
		param.put("accountSeq", param.getSessionAttribute("loginAccountSeq"));
		param.put("clientSeq", param.getSessionAttribute("loginClientSeq"));
		model.addAllAttributes(service.checkExcelUpload(param));
		return JSON_VIEW;
	}

	/**
	 * 상세조회
	 */
	@Operation(summary = "가입자 상세 조회", description = "특정 가입자의 상세 정보를 조회합니다.")
	@Parameters({
		@Parameter(name = "memberSeq", description = "가입자 시퀀스", example = "1", in = ParameterIn.PATH, schema = @Schema(type = "integer", format = "int64"))
