1	package com.ahope.ds.common.extension.resolver;
2	
3	import java.lang.annotation.Annotation;
4	
5	import jakarta.servlet.http.HttpServletRequest;
6	
7	import org.springframework.core.MethodParameter;
8	import org.springframework.web.bind.support.WebArgumentResolver;
9	import org.springframework.web.bind.support.WebDataBinderFactory;
10	import org.springframework.web.context.request.NativeWebRequest;
11	import org.springframework.web.method.support.HandlerMethodArgumentResolver;
12	import org.springframework.web.method.support.ModelAndViewContainer;
13	
14	import com.ahope.ds.common.bean.ParamMap;
15	import com.ahope.ds.common.exception.RuntimeLogicException;
16	import com.ahope.ds.common.extension.annotation.RequestParamMap;
17	import com.ahope.ds.common.util.CommonUtil;
18	
19	public class RequestParamMapArgumentResolver implements HandlerMethodArgumentResolver {
20		public Object resolveArgument(MethodParameter param,
21				ModelAndViewContainer mnv, NativeWebRequest request,
22				WebDataBinderFactory binderFactory) throws Exception {
23			
24			Annotation[] paramAnns = param.getParameterAnnotations();  
25			Class<?> paramType = param.getParameterType();  
26			   
27	        for (Annotation paramAnn : paramAnns) {
28	        	
29	        	if (RequestParamMap.class.isInstance(paramAnn)) {  
30	
31	        		if(paramType.isAssignableFrom(ParamMap.class)){
32	        			
